custom_css:
.egs-landing-wrapper {
	font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
	background-color: #f8fafc;
	min-height: 100vh;
}
.text-slate-800 { color: #1e293b !important; }
.text-blue-100 { color: #dbeafe !important; }
.text-blue-200 { color: #bfdbfe !important; }
.text-emerald { color: #059669 !important; }
.bg-emerald-subtle { background-color: #ecfdf5 !important; }
.text-amber { color: #d97706 !important; }
.bg-amber-subtle { background-color: #fffbeb !important; }
.text-purple { color: #7c3aed !important; }
.bg-purple-subtle { background-color: #f5f3ff !important; }
.bg-blue-subtle { background-color: #eff6ff !important; }
.egs-hero {
	background: linear-gradient(135deg, #1e3a8a 0%, #2563eb 60%, #3b82f6 100%);
	padding: 4rem 1rem 3.5rem 1rem;
	box-shadow: 0 4px 20px -2px rgba(30, 58, 138, 0.25);
}
.egs-pill-badge {
	background: rgba(255, 255, 255, 0.15);
	backdrop-filter: blur(8px);
	border: 1px solid rgba(255, 255, 255, 0.25);
	padding: 0.35rem 1rem;
	border-radius: 9999px;
	font-size: 0.825rem;
	font-weight: 600;
	color: #ffffff;
}
.egs-pulse-dot {
	width: 8px;
	height: 8px;
	background-color: #34d399;
	border-radius: 50%;
	display: inline-block;
	box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.7);
	animation: egs-pulse 2s infinite;
}
@keyframes egs-pulse {
	0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.7); }
	70% { transform: scale(1); box-shadow: 0 0 0 8px rgba(52, 211, 153, 0); }
	100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(52, 211, 153, 0); }
}
.egs-card {
	background: #ffffff;
	border-radius: 14px;
	transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
	border: 1px solid #e2e8f0 !important;
}
.egs-card:hover {
	transform: translateY(-5px);
	box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.08), 0 10px 10px -5px rgba(0, 0, 0, 0.04) !important;
}
.egs-card-public:hover { border-color: #a7f3d0 !important; }
.egs-card-checkin:hover { border-color: #bfdbfe !important; }
.egs-card-secure:hover { border-color: #fde68a !important; }
.egs-card-admin:hover { border-color: #ddd6fe !important; }
.egs-icon-box {
	width: 52px;
	height: 52px;
	border-radius: 12px;
	display: flex;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;
}
.egs-badge {
	font-size: 0.75rem;
	font-weight: 600;
	padding: 0.35rem 0.75rem;
	border-radius: 9999px;
	display: inline-flex;
	align-items: center;
}
.badge-dot { width: 6px; height: 6px; border-radius: 50%; display: inline-block; }
.egs-badge-public { background-color: #ecfdf5; color: #065f46; border: 1px solid #a7f3d0; }
.egs-badge-secure { background-color: #fffbeb; color: #92400e; border: 1px solid #fde68a; }
.egs-badge-admin { background-color: #f5f3ff; color: #5b21b6; border: 1px solid #ddd6fe; }
.egs-arrow-icon { transition: transform 0.2s ease-in-out; }
.egs-card:hover .egs-arrow-icon { transform: translateX(4px); }
@media (max-width: 768px) {
	.egs-hero { padding: 2.75rem 1rem 2.25rem 1rem; }
	.egs-hero h1 { font-size: 2rem; }
}
